from __future__ import annotations
from abc_creative_gold_v5_101_200_support import make_spec, register_craft
FACTS={
"AI Chip":"Processor/accelerator optimized for machine-learning calculations; running a model does not make the chip conscious.","Battery":"Electrochemical device converts stored chemical energy to electrical energy; polarity, voltage, chemistry, charging, and disposal must match the device.","Circuit Board":"Rigid/flexible substrate supports and electrically connects components through conductive traces and pads.","Display":"Device presents visual information using pixels, segments, LEDs, or other technologies; it shows data but does not create truth by itself.","Encoder":"Sensor/device converts position, motion, or another state into coded electrical/digital information; rotary and linear encoders are common.","FPGA":"Field-programmable gate array contains configurable digital logic blocks/interconnects that can be reprogrammed for hardware functions.","Gyroscope":"Sensor or spinning device measures/maintains orientation; electronic gyroscopes often measure angular rate using MEMS structures.","Heat Sink":"Thermally conductive structure spreads component heat into surrounding air or another cooling path; it does not generate cold.","Infrared Sensor":"Sensor detects infrared radiation or uses IR light for ranging/presence depending design; infrared is electromagnetic radiation beyond visible red.","Joystick":"Human input control reports direction and sometimes buttons/axes; it sends commands rather than directly moving a robot joint.","Keyboard":"Key-based input device sends codes/commands to a computer or controller; software interprets those inputs.","Laser Module":"Device makes coherent light; direct eye exposure can injure, so real modules need rated lab safety controls.","Motor":"Electromechanical actuator converts electrical energy into rotational or linear mechanical motion depending type.","Network Cable":"Wired medium carries data signals between network devices; connector/category and supported speed depend on cable standard.","Oscilloscope":"Instrument plots voltage versus time/signals; trained users connect probes within safe limits.","Proximity Sensor":"Sensor detects nearby objects without necessarily touching them; optical, capacitive, inductive, ultrasonic and other methods differ.","Quantum Sensor":"Sensor class uses quantum effects for precise measurement; it is not a quantum computer by definition.","Robot Arm":"Mechanical linkage with joints/actuators positions an end effector; controller and program determine commanded motion.","Servo":"Actuator system uses feedback to control position, speed, or torque; hobby servos typically combine motor, gears, sensor, and controller.","Touch Sensor":"Sensor detects contact or touch-related changes using capacitive, resistive, force, or other methods.","Ultrasonic Sensor":"Sensor emits/receives ultrasound above human hearing, often estimating distance from echo travel time; surfaces and environment affect readings.","Voltage Regulator":"Circuit maintains or converts output voltage within a specified range; it cannot safely ignore current, heat, or input limits.","Wheel Encoder":"Encoder measures wheel rotation to estimate speed/distance; wheel slip means estimated travel can differ from true ground movement.","X-ray Sensor":"Detector converts X-ray energy into signals for imaging; operation requires professional radiation controls.","Yaw Sensor":"Project label for sensor estimating rotation about a vertical/yaw axis, often using gyroscope or fused inertial data; drift/calibration can matter.","Zero-voltage Meter":"Project meter label for checking a zero/near-zero voltage condition; zero reading depends on instrument range, connection, and actual circuit state.","Arduino Board":"Microcontroller development-board family; processor, voltage, and pins depend on model.","Breadboard":"Reusable solderless prototyping board connects components through internal spring contacts; it is for low-voltage circuits, not mains electricity.","Digital Multimeter":"Instrument measures voltage, current, resistance and other quantities depending model; mode/range/probe placement must match the measurement.","Electric Motor":"Motor converts electrical energy to mechanical motion through electromagnetic interactions; many motor types use different drive electronics.","Firmware":"Software stored close to hardware controls low-level device behavior; it can be updated but must match device/version.","Gearbox":"Mechanical gear train changes speed, torque, or direction between input and output shafts.","H-bridge":"Electronic switching circuit drives current through a motor in either direction; shoot-through and voltage/current limits require proper control.","I2C Sensor":"Sensor communicating over I²C digital bus shares clock/data lines with addressed devices; voltage levels and addresses must be compatible.","Joint":"Robot joint provides one or more mechanical degrees of freedom; bearings, actuators, limits, and sensors shape motion.","Logic Gate":"Digital circuit implements Boolean operations such as AND, OR, or NOT on logic-level inputs.","Machine Vision Camera":"Camera captures images for automated analysis; algorithms infer features from pixels and can make errors.","Optical Sensor":"Sensor responds to light using photodiodes, phototransistors, imaging elements, or other optical methods.","Power Supply":"Source converts/provides electrical power at specified voltage/current; current capability and polarity must match load.","Relay":"Electrically controlled switch isolates or redirects circuits; electromechanical and solid-state relays behave differently.","Ultrasonic Module":"Packaged ultrasonic transmitter/receiver module often used for ranging; it needs correct voltage, timing, and geometry.","X-axis Motor":"Project label for a motor assigned to motion along an X axis; the motor itself is not inherently 'X-axis' without the machine coordinate system.","Daughter Board":"Secondary circuit board plugs/connects to a main board to add specialized functions.","Encoder Wheel":"Patterned wheel/disc works with a sensor to encode rotation; slot/mark count affects resolution.","Heat Sensor":"Broad sensor label for temperature/thermal detection; thermistors, IC sensors, thermocouples, and infrared sensors measure differently.","Interface Board":"Board adapts connectors, voltage levels, signals, or protocols between subsystems.","MOSFET":"Field-effect transistor used as an electronic switch/amplifier; gate voltage controls conduction and device limits must be respected.","USB Cable":"Cable carries power and/or data under USB standards; connector shape alone does not guarantee supported power or data rate.","X-shaped Robot Arm":"Project robot-arm model with X-like geometry; shape is a visual clue and does not define a standard industrial kinematic type.","Z-axis Sensor":"Project sensor assigned to a Z-axis measurement in a coordinate system; axis meaning depends on machine orientation and sensor type.","Capacitor":"Component stores electric charge/energy in an electric field; capacitance, voltage rating, polarity for some types, and discharge matter.","DAC":"Digital-to-analog converter turns digital numeric codes into corresponding analog voltage/current within its range and resolution.","LED":"Light-emitting diode produces light when current flows in forward direction; it needs current limiting appropriate to circuit.","Microcontroller":"Computer-on-chip combines CPU, memory and peripherals; programs determine behavior.","Sensor":"Device detects a physical quantity/event and converts it into usable data/signal; every sensor has limits, noise, and calibration considerations.","Transistor":"Semiconductor component controls current/voltage and can switch or amplify; bipolar and field-effect types differ.","UV Sensor":"Sensor measures ultraviolet intensity; measurement never requires deliberate skin/eye exposure.","X-ray Sensor Array":"Multiple X-ray detector elements form images; operation belongs in controlled professional systems.","High Voltage":"Electrical condition with serious shock/arc hazards; thresholds depend on standards and it is never preschool experimentation.",}
ACTIONS={k:"Point only; real electrical/lab equipment stays with trained adults." for k in ("Laser Module","Oscilloscope","X-ray Sensor","Zero-voltage Meter","Digital Multimeter","Power Supply","Relay","MOSFET","Capacitor","X-ray Sensor Array","High Voltage")}
ACTIONS.update({"Battery":"Point; match polarity/chemistry only under adult guidance.","Motor":"Rotate one finger slowly; no powered mechanism handling.","Electric Motor":"Rotate one finger slowly; no powered mechanism handling.","Robot Arm":"Bend one elbow slowly; keep real robot work envelope clear.","X-shaped Robot Arm":"Air-trace X geometry; no real robot interaction.","UV Sensor":"Point; no intentional UV exposure.","Ultrasonic Sensor":"Point; trace an out-and-back echo line.","Machine Vision Camera":"Frame a picture with fingers; say image analysis can be wrong."})
